// GitHub webhook payloads we care about:
//   - push:           commits[] + ref + pusher + repository
//   - pull_request:   action, number, pull_request.title/state/html_url, sender
//
// X-GitHub-Event header tells us which one. Read from $input.headers.
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || $input.first().json || {};
const event = (headers['x-github-event'] || '').toLowerCase();

const repo = body.repository?.full_name || 'unknown-repo';
let title, message, url;

if (event === 'push') {
  const ref = (body.ref || '').replace('refs/heads/', '');
  const pusher = body.pusher?.name || body.sender?.login || 'someone';
  const commits = body.commits || [];
  const head = commits[commits.length - 1] || {};
  const shortMsg = (head.message || '').split('\n')[0].slice(0, 140);
  title = `${repo} · push to ${ref}`;
  message = `${pusher}: ${shortMsg || '(no message)'}\n${commits.length} commit(s).`;
  url = head.url || body.compare || body.repository?.html_url || '';
} else if (event === 'pull_request') {
  const pr = body.pull_request || {};
  const action = body.action || 'updated';
  title = `${repo} · PR ${action}`;
  message = `#${pr.number || '?'}: ${pr.title || '(no title)'}\nby ${pr.user?.login || 'someone'} · state ${pr.state}`;
  url = pr.html_url || '';
} else if (event === 'ping') {
  title = `${repo} · webhook ping`;
  message = 'GitHub successfully reached n8n.';
  url = body.repository?.html_url || '';
} else {
  // Drop noisy events silently (don't punish the source).
  return [{ json: { skip: true, event } }];
}

return [{
  json: {
    skip: false,
    pushover: {
      title,
      message,
      priority: 0,
      url,
      url_title: 'View on GitHub'
    }
  }
}];
